function render(){ $("hfCatalogTitle").textContent=(website.brand?.name||website.name)+" · Products & Categories";$("hfCatalogPages").href="./website-pages.html?template="+encodeURIComponent(templateKey);$("hfCatalogOrders").href="./website-orders.html?template="+encodeURIComponent(templateKey);$("hfCatalogPreview").href="../storefront.html?site="+encodeURIComponent(website.slug)+(website.status==="published"?"":"&preview=1");$("hfCatalogPreview").textContent=website.status==="published"?"Open live website ↗":"Open private preview ↗";$("hfCatalogPreview").classList.toggle("is-live",website.status==="published");$("hfCatalogPreview").title=website.status==="published"?"Open the public storefront in a new tab":"Open the private owner preview; publish the website to make it public.";fillCategoryOptions();renderStats();renderCategories();renderProducts();fillOperationsForm();}
async function reload(){const data=await window.WPNeonBuilderApi.loadWebsiteCatalog(website);categories=data.categories;products=data.products;render();}
function resetCategory(){ $("hfCategoryForm").reset();$("hfCategoryForm").elements.id.value="";$("hfCategoryCancel").hidden=true;}
function resetProduct(){const f=$("hfProductForm");f.reset();f.elements.id.value="";f.elements.unit.value="piece";f.elements.stock.value="0";f.elements.minimum_order_quantity.value="1";f.elements.is_active.checked=true;f.elements.real_inventory_verified.checked=false;$("hfProductFormHeading").textContent="Add a product";$("hfProductSave").textContent="Save product";$("hfProductCancel").hidden=true;fillCategoryOptions();}
function editCategory(id){const c=categories.find(x=>x.id===id);if(!c)return;const f=$("hfCategoryForm");f.elements.id.value=c.id;f.elements.name.value=c.name;f.elements.slug.value=c.slug;$("hfCategoryCancel").hidden=false;f.scrollIntoView({behavior:"smooth",block:"center"});}
