async function toggleProduct(id,isActive){try{await window.WPNeonBuilderApi.setWebsiteProductActive(website,id,!isActive);await reload();status("Product "+(!isActive?"restored":"archived")+" successfully.","success");}catch(e){status(e.message||"Could not update product status.","warning");}}
