function csvCell(value){const s=String(value??"");return '"'+s.replaceAll('"','""')+'"';}
function exportProductsCsv(){const headers=["name","category_slug","sku","barcode","price","compare_at_price","unit","stock","minimum_order_quantity","brand","pack_size","origin","grade","expiry_date","farm_name","image_url","description","is_active","real_inventory_verified"];const rows=products.map(p=>{const a=p.attributes||{},cat=categories.find(c=>c.id===p.category_id);return [p.name,cat?.slug||"",p.sku||"",a.barcode||"",p.price,p.compare_at_price??"",p.unit||"piece",p.stock,a.minimum_order_quantity||1,a.brand||"",a.pack_size||"",a.origin||"",a.grade||"",a.expiry_date||"",a.farm_name||"",p.image_url||"",p.description||"",p.is_active?"true":"false",a.inventory_verified===true&&a.demo!==true?"true":"false"];});const csv=[headers,...rows].map(row=>row.map(csvCell).join(",")).join("\r\n");const blob=new Blob(["\ufeff",csv],{type:"text/csv;charset=utf-8"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=(website.slug||"store")+"-products.csv";a.click();URL.revokeObjectURL(url);status("Product CSV exported. The real-inventory verification column is included.","success");}
function parseProductsCsv(text){const rows=[];let row=[],value="",quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(quoted){if(ch==='"'&&text[i+1]==='"'){value+='"';i++;}else if(ch==='"')quoted=false;else value+=ch;}else if(ch==='"')quoted=true;else if(ch===","){row.push(value);value="";}else if(ch==="\n"){row.push(value);rows.push(row);row=[];value="";}else if(ch!=="\r")value+=ch;}if(value.length||row.length){row.push(value);rows.push(row);}if(!rows.length)return[];const headers=rows.shift().map(x=>String(x||"").trim().toLowerCase());return rows.filter(r=>r.some(x=>String(x||"").trim())).map(r=>Object.fromEntries(headers.map((h,i)=>[h,String(r[i]||"").trim()])));}
async function importProductsCsv(file){const records=parseProductsCsv(await file.text());if(!records.length)throw new Error("The CSV file has no product rows.");const existingBySku=new Map(products.filter(p=>p.sku).map(p=>[String(p.sku).toLowerCase(),p]));let imported=0,failed=0;const errors=[];for(let i=0;i<records.length;i++){const r=records[i];try{if(!r.name||!r.price||r.stock==="")throw new Error("Name, price and stock are required.");const category=categories.find(c=>r.category_slug&&(c.slug.toLowerCase()===r.category_slug.toLowerCase()||c.name.toLowerCase()===r.category_slug.toLowerCase()));if(r.category_slug&&!category)throw new Error("Unknown category_slug: "+r.category_slug);const existing=existingBySku.get(String(r.sku||"").toLowerCase());await window.WPNeonBuilderApi.saveWebsiteProduct(website,{id:existing?.id||"",name:r.name,category_id:category?.id||"",sku:r.sku||"",barcode:r.barcode||"",price:r.price,compare_at_price:r.compare_at_price||"",unit:r.unit||"piece",stock:r.stock,minimum_order_quantity:r.minimum_order_quantity||1,brand:r.brand||"",pack_size:r.pack_size||"",origin:r.origin||"",grade:r.grade||"",expiry_date:r.expiry_date||"",farm_name:r.farm_name||"",image_url:r.image_url||"",description:r.description||"",is_active:!["false","0","no"].includes(String(r.is_active||"true").toLowerCase()),real_inventory_verified:["true","1","yes"].includes(String(r.real_inventory_verified||"false").toLowerCase())});imported++;}catch(e){failed++;errors.push("Row "+(i+2)+": "+(e.message||"Import failed"));}}await reload();status(imported+" product rows imported; "+failed+" skipped."+(errors.length?" "+errors.slice(0,3).join(" | "):""),failed?"warning":"success");}

