async function init(){if(!window.WPNeonBuilderApi)throw new Error("Neon builder API unavailable.");const catalog=await window.WPNeonBuilderApi.loadTemplateCatalog(),meta=catalog.find(x=>x.template_key===templateKey);if(!meta)throw new Error("This template is not active in the Neon catalog.");website=await window.WPNeonBuilderApi.ensureWebsite(templateKey,meta.name);await reload();status("NEON CONNECTED · "+categories.length+" categories · "+products.length+" products","success");}
const wait=()=>{const ready=window.WPAuthReady;if(!ready||typeof ready.then!=="function"){status("Secure admin session unavailable.","warning");return;}ready.then(async session=>{if(!session?.user?.id){status("Admin access required.","warning");return;}try{await init();}catch(e){console.error(e);status(e.message||"Could not load catalogue.","warning");}}).catch(e=>status(e.message||"Secure admin initialization failed.","warning"));};
if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",wait,{once:true});else wait();
})();

