function addToCart(id,quantity=1,buyNow=false){const p=getProduct(id);if(!canOrderProduct(p)){const a=p?.attributes||{};notify(Boolean(a.prescription_required)&&!Boolean(a.prescription_verified)?"Prescription-only items require pharmacist review before checkout.":p&&Number(p.stock)>0?"This item is in preview until the store verifies its inventory.":"This product is currently unavailable.");return;}const qty=Math.max(quantityMinimum(p),Number(quantity)||quantityMinimum(p));const row=state.cart.find(x=>x.product_id===id);const next=(row?.quantity||0)+qty;if(next>Number(p.stock)){notify("The requested quantity is not available in stock.");return;}if(row)row.quantity=next;else state.cart.push({product_id:id,quantity:qty});saveLocal();notify("Added to your basket.");if(buyNow)location.href=pageUrl("checkout");else render();}
