function reorderTrackedOrder(){const items=state.lastTrackedOrder?.items||[],ready=[];for(const item of items){const id=item.product?.id,p=getProduct(id),quantity=Number(item.quantity||0);if(!p||quantity<=0||quantity<Number(p.attributes?.minimum_order_quantity||1))continue;const current=state.cart.find(x=>x.product_id===id),next=(current?.quantity||0)+quantity;if(next>Number(p.stock))continue;ready.push({id,quantity});}if(!ready.length){notify("The previous order's products are no longer available in the required quantities.");return;}for(const item of ready){const row=state.cart.find(x=>x.product_id===item.id);if(row)row.quantity+=item.quantity;else state.cart.push({product_id:item.id,quantity:item.quantity});}saveLocal();notify("Available items from your previous order were added to the basket.");location.href=pageUrl("cart");}
async function submitQuote(e){e.preventDefault();const form=e.currentTarget,status=root.querySelector("#sfBulkStatus"),button=root.querySelector("#sfBulkSubmit"),data=new FormData(form);if(preview){status.textContent="Quote submissions are disabled in private preview. Use the isolated QA workflow for acceptance testing.";return;}button.disabled=true;status.textContent="Saving your quote request…";try{const message=String(data.get("message")||"").trim(),items=message.split(/\r?\n/).map(line=>line.trim()).filter(Boolean).slice(0,100).map(description=>({description:description.slice(0,500)}));const business={company_name:String(data.get("company_name")||"").trim(),contact_name:String(data.get("contact_name")||"").trim(),phone:String(data.get("phone")||"").trim(),email:String(data.get("email")||"").trim(),business_type:String(data.get("business_type")||""),tax_id:String(data.get("tax_id")||"").trim()};if(!items.length)throw new Error("Add at least one product and quantity line.");const result=await storefrontApi().submitQuoteRequest(siteSlug,business,items,message.slice(0,2000));status.textContent=(result?.message||"Your quote request has been received.")+" Reference: "+(result?.quote_number||"saved");form.reset();}catch(err){status.textContent=err.message||"Your quote request could not be saved. Please try again.";}finally{button.disabled=false;}}
async function getPreviewToken(){return null;}
async function boot(){if(!siteSlug){throw new Error("A storefront site address is required.");}state.previewToken=await getPreviewToken();const data=await storefrontApi().loadStorefrontData(siteSlug,{token:state.previewToken,preview});state.website=data.website;state.pages=data.pages;state.documents=data.documents;state.categories=data.categories;state.products=data.products;state.deliveryZones=data.deliveryZones||[];state.priceTiers=data.priceTiers||[];state.page=params.get("page")||"home";if(!state.pages.some(p=>p.page_key===state.page)&&!state.documents.some(d=>d.page_key===state.page))state.page="home";if(state.website.status!=="published"||preview||state.website.settings?.showcase_mode===true){let robots=document.querySelector('meta[name="robots"]');if(!robots){robots=document.createElement("meta");robots.name="robots";document.head.appendChild(robots);}robots.content="noindex,nofollow";}else{document.querySelector('meta[name="robots"]')?.remove();}loadLocal();render();}
boot().catch(err=>{console.error("Storefront load failed",err);root.innerHTML='<main class="sf-main"><div class="sf-empty"><h3>Storefront could not be opened</h3><p>'+esc(err.message||"Please try again later.")+'</p>'+(preview?'<a class="sf-btn" href="./admin/website-pages.html">Back to Website Pages</a>':'')+'</div></main>';});
})();

